alter table public.contracts add column status text not null default 'ACTIVE' check(status in('DRAFT','ACTIVE','SUSPENDED','EXPIRED','CLOSED')), add column description text, add column operational_owner_id uuid references public.user_profiles(id) on delete set null, add column customer_owner_name text, add column renewal_automatic boolean not null default false, add column renewal_notice_days integer check(renewal_notice_days between 1 and 730), add column service_hours text, add column scope_summary text, add column exclusions_summary text;
create index contracts_governance_idx on public.contracts(organization_id,status,ends_at);
create or replace function public.contract_expiry_alerts(target_days integer default 60) returns table(contract_id uuid,organization_id uuid,ends_at date,days_remaining integer) language sql stable security definer set search_path=public as $$ select id,organization_id,ends_at,(ends_at-current_date)::integer from public.contracts where status='ACTIVE' and ends_at is not null and ends_at between current_date and current_date+target_days and public.has_organization_role(organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[]); $$;
revoke all on function public.contract_expiry_alerts(integer) from public; grant execute on function public.contract_expiry_alerts(integer) to authenticated;
